stage "Durable Object location: can an object learn where it is? (ADR 0017)"
spike_do() {
  begin R_DO || return 0
  local dir="$WORK/links-data" url i hint line table="" props="" distinct worker_colo="?" away=0
  say "This deploys ${BOLD}$LD_WORKER${RESET}, a stand-in for links-data: a SQLite Durable Object class"
  say "declared with 'exports', a '$WORKFLOW_NAME' Workflow, and a keyed workers.dev route."
  say "Stages 10 to 12 reuse it."
  confirm "Deploy it?" || return 0
  write_ld_worker
  loud "$LOGS/ld-deploy.log" wr "$CF_SETUP_TOKEN" "$dir" deploy || die "the deploy failed; see above."
  url=$(grep -oE 'https://[A-Za-z0-9.-]+\.workers\.dev' "$LOGS/ld-deploy.log" | tail -n 1 || true)
  if [[ -z "$url" ]]; then ask LD_URL "Paste the workers.dev URL Wrangler printed:"; url="$LD_URL"; fi
  [[ "$url" == https://*.workers.dev* ]] || die "that isn't a workers.dev URL."
  url="${url%/}"; LD_URL="$url"
  write_env LD_URL "$url"
  record WORKERS_SUBDOMAIN "$(sed -E 's#https://[^.]+\.([^.]+)\.workers\.dev.*#\1#' <<<"$url")"
  record LD_DEPLOYED yes
  # A fresh workers.dev subdomain can take minutes to resolve; wait for a 200.
  say "Waiting for $url to answer (a new workers.dev subdomain can take a few minutes)..."
  for i in $(seq 1 60); do
    if probe "$url/?k=$SPIKE_KEY&hint=weur&name=ready-$RUN" && [[ "$PROBE_STATUS" == 200 || "$PROBE_STATUS" == 403 ]]; then break; fi
    sleep 5
  done
  if [[ "$PROBE_STATUS" != 200 ]]; then
    bad "still no 200 after five minutes: HTTP ${PROBE_STATUS:-none}; the reply is in $LOGS/ld-probe.log"
    note "$(excerpt "$LOGS/ld-probe.log")"
    note "Try it yourself: curl -i '$url/?k=<SPIKE_KEY from state.env>&hint=weur&name=x'"
    note "A 403 means the key differs; an HTML error page means the Worker threw; nothing means DNS."
    confirm "Carry on probing anyway?" || die "re-run the wizard once the URL answers; the deploy is kept."
  fi
  say "Asking five new objects, each created with a different location hint, where they are."
  say "Each fetches cloudflare.com/cdn-cgi/trace from inside the object and reports its 'colo'."
  printf '\n'
  printf '  %s%-6s %-12s %-12s %-22s%s\n' "$BOLD" "hint" "object says" "trace loc" "Worker ran in" "$RESET"
  for hint in wnam enam weur apac oc; do
    line=""
    for i in 1 2 3; do
      if probe "$url/?k=$SPIKE_KEY&hint=$hint&name=direct-$hint-$RUN-$i" && jq -e . "$PROBE_BODY" >/dev/null 2>&1; then
        line=$(cat "$PROBE_BODY"); break
      fi
      sleep 3
    done
    if [[ -z "$line" ]]; then
      bad "$hint: no JSON came back (HTTP ${PROBE_STATUS:-none}; reply kept in $LOGS/ld-probe.log)"
      table+="${hint}→error "; continue
    fi
    worker_colo=$(jq -r '.worker_colo // "?"' <<<"$line")
    printf '  %-6s %-12s %-12s %-22s\n' "$hint" "$(jq -r '.trace_colo // .trace_error // "none"' <<<"$line")" \
      "$(jq -r '.trace_loc // "-"' <<<"$line")" "$worker_colo"
    table+="${hint}→$(jq -r '.trace_colo // "none"' <<<"$line") "
    if [[ "$(jq -r '.trace_colo // ""' <<<"$line")" != "$worker_colo" ]]; then away=$((away + 1)); fi
    props=$(jq -r '"ctx: " + (.ctx_properties | join(",")) + "; ctx.id: " + (.id_properties | join(","))' <<<"$line")
  done
  distinct=$(tr ' ' '\n' <<<"$table" | sed -n 's/.*→//p' | grep -vE '^(none|error)$' | sort -u | wc -l | tr -d ' ')
  printf '\n'
  note "Properties on the object's own context (nothing documented names a place):"
  note "$props"
  printf '\n'
  say "Colos are airport codes. The method works if each object's colo sits in its hint's region"
  say "(wnam: western North America, enam: eastern, weur: western Europe, apac: Asia-Pacific,"
  say "oc: Oceania), and not simply wherever the Worker ran ($worker_colo)."
  note "$distinct distinct colo(s); $away of 5 differ from the Worker's own."
  ask DO_NOTE "Optional note (anything odd, or a context property that names a place):"
  if confirm "Do the colos match their hints?"; then
    conclude DO no "" "A Durable Object learns its colo by fetching https://www.cloudflare.com/cdn-cgi/trace from inside itself and reading 'colo='. Objects created with five hints reported: $table(Worker ran in $worker_colo). Context properties: $props. ${DO_NOTE:+Note: $DO_NOTE}"
  else
    conclude DO yes "The touch step reports only that each shard answered (slice 1.5)." "No method found. cdn-cgi/trace from inside the object reported: $table(Worker ran in $worker_colo), which doesn't track the hints. Context properties: $props. ${DO_NOTE:+Note: $DO_NOTE}"
  fi
}
spike_do
pause

