stage "Create the two role tokens ADR 0024 describes"
role_tokens() {
  need LD_DEPLOYED "Stage 8 hasn't deployed $LD_WORKER yet; the tokens are scoped to it. Re-run the wizard." || return 0
  if [[ -n "$CF_ADMIN_TOKEN" && -n "$CF_PLAN_TOKEN" ]]; then
    ok "both role tokens are already saved"
    confirm "Enter them again?" || return 0
  fi
  say "Stages 10 and 11 ask what ADR 0024's roles can do, so they need tokens with exactly"
  say "those roles. Per-Worker roles exist only on account-owned tokens (shipped 2026-09-15)."
  open_url "https://dash.cloudflare.com/$CF_ACCOUNT_ID/home"
  step "${BOLD}Manage Account → Account API Tokens → Create Token${RESET}."
  step "Token 1, the production-admin role: name ${BOLD}$PREFIX-admin${RESET}, scope ${BOLD}Specified Workers${RESET},"
  step "    select ${BOLD}$LD_WORKER${RESET}, role ${BOLD}Editor${RESET}. Nothing else. Expire in a week."
  ask_secret CF_ADMIN_TOKEN "Paste the $PREFIX-admin token:"
  step "Token 2, the production-plan role: name ${BOLD}$PREFIX-plan${RESET}, scope ${BOLD}Specified Workers${RESET},"
  step "    select ${BOLD}$LD_WORKER${RESET}, role ${BOLD}Metadata Read-Only${RESET}. Nothing else."
  ask_secret CF_PLAN_TOKEN "Paste the $PREFIX-plan token:"
  [[ -n "$CF_ADMIN_TOKEN" && -n "$CF_PLAN_TOKEN" ]] || die "both tokens are required."
  [[ "$CF_ADMIN_TOKEN" != "$CF_PLAN_TOKEN" ]] || die "the two tokens are the same one."
  token_ok "$CF_ADMIN_TOKEN" || die "Cloudflare doesn't accept the admin token (HTTP $CF_STATUS: $(cf_error))."
  token_ok "$CF_PLAN_TOKEN" || die "Cloudflare doesn't accept the plan token (HTTP $CF_STATUS: $(cf_error))."
  ok "both tokens are active"
  write_env CF_ADMIN_TOKEN "$CF_ADMIN_TOKEN"; write_env CF_PLAN_TOKEN "$CF_PLAN_TOKEN"
  note "This screen is new. If its labels differ from the ones above, say how:"
  ask ROLE_TOKEN_NOTE "Optional note on what the token screen actually offered:"
  write_env ROLE_TOKEN_NOTE "$ROLE_TOKEN_NOTE"
}
role_tokens
pause

