stage "Workflows: can Editor on the Worker start and read an instance? (ADR 0031)"
# wf_try TOKEN: create an instance and poll it. Sets WF_CREATE, WF_READ, WF_FINAL, WF_OUT.
WF_CREATE=""; WF_READ=""; WF_FINAL=""; WF_OUT=""; WF_ERR=""
wf_try() {
  local token="$1" id i
  WF_READ="not tried"; WF_FINAL="not reached"; WF_OUT=""; WF_ERR=""
  cf "$token" POST "/accounts/$CF_ACCOUNT_ID/workflows/$WORKFLOW_NAME/instances" '{}'
  WF_CREATE="$CF_STATUS"
  id=$(jq -r '.result.id // empty' "$CF_BODY" 2>/dev/null || true)
  if [[ "$CF_STATUS" != 2* || -z "$id" ]]; then WF_ERR=$(cf_error); return 1; fi
  for i in $(seq 1 60); do
    cf "$token" GET "/accounts/$CF_ACCOUNT_ID/workflows/$WORKFLOW_NAME/instances/$id"
    WF_READ="$CF_STATUS"
    if [[ "$CF_STATUS" != 2* ]]; then WF_ERR=$(cf_error); return 1; fi
    WF_FINAL=$(jq -r '.result.status // "unknown"' "$CF_BODY")
    case "$WF_FINAL" in complete|errored|terminated) break ;; esac
    sleep 3
  done
  WF_OUT=$(jq -r '[.result.output[]? | "\(.hint)→\(.trace_colo // "none")"] | join(" ")' "$CF_BODY" 2>/dev/null || true)
  [[ "$WF_FINAL" == complete ]]
}
spike_wf() {
  need CF_ADMIN_TOKEN "Stage 9 hasn't saved the role tokens yet; re-run the wizard to do it." || return 0
  begin R_WF || return 0
  local first added="" tries=0
  say "With the $PREFIX-admin token (Editor on $LD_WORKER only), the wizard starts one"
  say "'$WORKFLOW_NAME' instance over the Workflows REST API and polls it until it ends."
  if wf_try "$CF_ADMIN_TOKEN"; then
    ok "created (HTTP $WF_CREATE), read (HTTP $WF_READ), ended '$WF_FINAL'"
    [[ -z "$WF_OUT" ]] || note "the Workflow's placement report: $WF_OUT"
    conclude WF no "" "Editor on the Worker is enough: create instance HTTP $WF_CREATE, get instance HTTP $WF_READ, final status '$WF_FINAL'. ${WF_OUT:+Placement report from inside the Workflow: $WF_OUT.} ${ROLE_TOKEN_NOTE:+Token screen note: $ROLE_TOKEN_NOTE}"
    return 0
  fi
  first="create HTTP $WF_CREATE, get HTTP $WF_READ, final '$WF_FINAL'${WF_ERR:+, error: $WF_ERR}"
  bad "with Editor alone: $first"
  say "Control: the same calls with the setup token, to prove the Workflow itself works."
  if wf_try "$CF_SETUP_TOKEN"; then ok "the setup token can (final '$WF_FINAL'), so this is a permissions answer"
  else
    warn "The setup token fails too (create HTTP $WF_CREATE, get HTTP $WF_READ, final '$WF_FINAL' $WF_ERR)."
    warn "That is a broken Workflow or endpoint, not a permissions answer. Nothing recorded; look at"
    warn "the Workflow in the dashboard, then run this stage again."
    return 0
  fi
  say "Now find the narrowest permission that fixes it. Edit the ${BOLD}$PREFIX-admin${RESET} token:"
  open_url "https://dash.cloudflare.com/$CF_ACCOUNT_ID/home"
  step "Manage Account → Account API Tokens → $PREFIX-admin → Edit."
  step "Add ONE permission, the narrowest that names Workflows. If none does, the documented"
  step "one for creating an instance is the account permission 'Workers Scripts: Edit'."
  while :; do
    tries=$((tries + 1))
    ask WF_ADDED "What did you add (exactly as the dashboard names it)? Empty to give up:"
    if [[ -z "$WF_ADDED" ]]; then break; fi
    added="$WF_ADDED"
    sleep 5
    if wf_try "$CF_ADMIN_TOKEN"; then ok "with '$added': created, read, ended '$WF_FINAL'"; break; fi
    bad "still failing with '$added': create HTTP $WF_CREATE, get HTTP $WF_READ $WF_ERR"
    added=""
    step "Remove that one and try another, or leave the answer empty to give up."
    [[ "$tries" -lt 6 ]] || break
  done
  if [[ -n "$added" ]]; then
    conclude WF yes "production-admin gains '$added', and ADR 0024's table says so (slices 1.4, 1.5)." "Editor on the Worker is not enough ($first). With '$added' added: create HTTP $WF_CREATE, get HTTP $WF_READ, final '$WF_FINAL'. ${ROLE_TOKEN_NOTE:+Token screen note: $ROLE_TOKEN_NOTE}"
  else
    conclude WF yes "production-admin needs a Workflows permission that this spike didn't find; settle it before slice 1.4." "Editor on the Worker is not enough ($first), and no added permission was found to fix it."
  fi
}
spike_wf
pause

