stage "The tag: deploy --tag with exports, read it back, versions upload (ADR 0031)"
spike_tag() {
  need CF_PLAN_TOKEN "Stage 9 hasn't saved the role tokens yet; re-run the wizard to do it." || return 0
  begin R_TAG || return 0
  local dir="$WORK/links-data" tag tag2 rc deploy_by="the Editor token" vid found="" probes="" p hit upload
  tag=$(openssl rand -hex 32); tag2=$(openssl rand -hex 32)
  write_ld_worker
  say "Deploying $LD_WORKER with --tag <64 hex characters>, as the $PREFIX-admin (Editor) token:"
  rc=0; loud "$LOGS/tag-deploy.log" wr "$CF_ADMIN_TOKEN" "$dir" deploy --tag "$tag" --message "spike $ISSUE_NUMBER tag" || rc=$?
  if [[ "$rc" != 0 ]]; then
    bad "the Editor token couldn't deploy: $(excerpt "$LOGS/tag-deploy.log")"
    deploy_by="the setup token (the Editor token's deploy failed: $(excerpt "$LOGS/tag-deploy.log"))"
    rc=0; loud "$LOGS/tag-deploy-setup.log" wr "$CF_SETUP_TOKEN" "$dir" deploy --tag "$tag" --message "spike $ISSUE_NUMBER tag" || rc=$?
    if [[ "$rc" != 0 ]]; then
      conclude TAG yes "plan reads the bundle hash from the GitHub deployment record (slice 1.5)." "wrangler $WRANGLER_VERSION deploy --tag failed on a Worker with exports: $(excerpt "$LOGS/tag-deploy-setup.log")"
      return 0
    fi
    cp "$LOGS/tag-deploy-setup.log" "$LOGS/tag-deploy.log"
  fi
  ok "deployed with the tag"
  vid=$(grep -i 'version id' "$LOGS/tag-deploy.log" | grep -oE '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' | tail -n 1 || true)
  say "Reading it back with the $PREFIX-plan token (Metadata Read-Only), every way there is:"
  # probe LABEL PATH: one GET with the plan token; does the body hold the tag?
  probe() {
    cf "$CF_PLAN_TOKEN" GET "$2"
    if grep -q "$tag" "$CF_BODY" 2>/dev/null; then hit="tag found"; [[ -n "$found" ]] || found="$1"
    else hit="no tag"; fi
    if [[ "$hit" == "tag found" ]]; then ok "$1: HTTP $CF_STATUS, $hit"; else bad "$1: HTTP $CF_STATUS, $hit $(cf_error)"; fi
    probes+="$1: HTTP $CF_STATUS, $hit. "
  }
  probe "GET /workers/scripts/{name}/versions" "/accounts/$CF_ACCOUNT_ID/workers/scripts/$LD_WORKER/versions"
  if [[ -n "$vid" ]]; then
    probe "GET /workers/scripts/{name}/versions/{id}" "/accounts/$CF_ACCOUNT_ID/workers/scripts/$LD_WORKER/versions/$vid"
  fi
  probe "GET /workers/scripts/{name}/deployments" "/accounts/$CF_ACCOUNT_ID/workers/scripts/$LD_WORKER/deployments"
  probe "GET /workers/workers/{name}/versions (beta API, name used as the id)" "/accounts/$CF_ACCOUNT_ID/workers/workers/$LD_WORKER/versions"
  for p in "versions list --json" "versions view ${vid:-none} --json" "deployments status --json"; do
    [[ "$p" != *none* ]] || continue
    rc=0
    # shellcheck disable=SC2086
    quiet "$LOGS/tag-cli.log" wr "$CF_PLAN_TOKEN" "$dir" $p || rc=$?
    if grep -q "$tag" "$LOGS/tag-cli.log"; then hit="tag found"; [[ -n "$found" ]] || found="wrangler ${p%% --json}"; ok "wrangler $p: exit $rc, $hit"
    else hit="no tag"; bad "wrangler $p: exit $rc, $hit"; fi
    probes+="wrangler $p: exit $rc, $hit. "
  done
  say "And wrangler versions upload on the same config, with the setup token:"
  rc=0; loud "$LOGS/tag-upload.log" wr "$CF_SETUP_TOKEN" "$dir" versions upload --tag "$tag2" --message "spike $ISSUE_NUMBER upload" || rc=$?
  if [[ "$rc" == 0 ]]; then upload="succeeds (exit 0)"; else upload="fails (exit $rc): $(excerpt "$LOGS/tag-upload.log")"; fi
  note "versions upload $upload"
  if [[ -n "$found" ]]; then
    conclude TAG no "" "wrangler $WRANGLER_VERSION deploy --tag works on a Worker with exports (deployed by $deploy_by). The Metadata Read-Only token reads the tag back; first hit: $found. All probes: $probes wrangler versions upload on the same config $upload"
  else
    conclude TAG yes "plan reads the bundle hash from the GitHub deployment record (slice 1.5)." "wrangler $WRANGLER_VERSION deploy --tag ran (by $deploy_by), but the Metadata Read-Only token can't read the tag back. Probes: $probes wrangler versions upload on the same config $upload"
  fi
}
spike_tag
pause

