stage "Remove every throwaway resource"
cleanup() {
  local c repo key dir="$WORK/links-data" headers
  if [[ -n "$PENDING" ]]; then
    warn "Not run yet: $PENDING"
    warn "Removing things now ends those spikes. The KV, retention and Dependabot ones need their"
    warn "resources until stages 15 to 17 have recorded a result."
    confirm "Remove everything anyway?" || { SKIPPED+=("re-run the wizard to finish: $PENDING, then remove the throwaway resources (this stage)"); return 0; }
  else
    confirm "Every spike is recorded. Remove the Workers, KV namespace, bucket and repos now?" \
      || { SKIPPED+=("remove the throwaway resources: re-run the wizard and answer yes at the last stage"); return 0; }
  fi
  if [[ -n "$CF_SETUP_TOKEN" ]]; then
    say "Workers (Wrangler asks you to confirm each delete):"
    if [[ -d "$dir" ]]; then
      wr "$CF_SETUP_TOKEN" "$dir" workflows delete "$WORKFLOW_NAME" || warn "couldn't delete the Workflow $WORKFLOW_NAME; check Workers → Workflows in the dashboard"
      wr "$CF_SETUP_TOKEN" "$dir" delete --name "$LD_WORKER" || SKIPPED+=("delete the Worker $LD_WORKER in the dashboard")
    fi
    wr "$CF_SETUP_TOKEN" "$WORK" delete --name "$KV_WORKER" || SKIPPED+=("delete the Worker $KV_WORKER in the dashboard")
    if [[ -n "$KV_NAMESPACE_ID" ]]; then
      wr "$CF_SETUP_TOKEN" "$WORK" kv namespace delete --namespace-id "$KV_NAMESPACE_ID" --skip-confirmation \
        || SKIPPED+=("delete the KV namespace $KV_WORKER in the dashboard")
    fi
    say "The bucket's objects, then the bucket:"
    for key in $(get STATE_KEYS); do
      wr "$CF_SETUP_TOKEN" "$WORK" r2 object delete "$BUCKET/$key" --remote >/dev/null 2>&1 || true
      wr "$CF_SETUP_TOKEN" "$WORK" r2 object delete "$BUCKET/$key.tflock" --remote >/dev/null 2>&1 || true
    done
    if wr "$CF_SETUP_TOKEN" "$WORK" r2 bucket delete "$BUCKET"; then ok "deleted the bucket $BUCKET"
    else
      warn "the bucket isn't empty or couldn't be deleted"
      SKIPPED+=("empty and delete the R2 bucket $BUCKET (dashboard: the bucket → Settings → Empty Bucket, then Delete)")
    fi
  fi
  say "The tokens. Only you can delete these:"
  open_url "https://dash.cloudflare.com/$CF_ACCOUNT_ID/home"
  step "Manage Account → Account API Tokens: delete $PREFIX-setup, $PREFIX-admin and $PREFIX-plan."
  step "R2 → Account Details → API Tokens → Manage: delete $PREFIX-rw and $PREFIX-ro."
  step "While there, check Workers & Pages, Workers KV, R2 and Workflows for anything named $PREFIX-…"
  if ! confirm "Are all five tokens deleted and nothing named $PREFIX-… left?"; then
    SKIPPED+=("delete the Cloudflare tokens $PREFIX-setup, $PREFIX-admin, $PREFIX-plan, $PREFIX-rw, $PREFIX-ro")
  fi
  say "The GitHub repos:"
  headers=$(gh api -i user 2>/dev/null | grep -i '^x-oauth-scopes:' || true)
  if ! grep -qw delete_repo <<<"$headers"; then
    note "gh needs the 'delete_repo' scope to delete a repo."
    if confirm "Run: gh auth refresh -h github.com -s delete_repo ?"; then
      gh auth refresh -h github.com -s delete_repo || warn "gh auth refresh failed"
    fi
  fi
  for repo in "$RET_REPO" "$DBOT_CONSUMER" $(for c in $DBOT_CASES; do printf '%s ' "$GH_LOGIN/$PREFIX-dbot-src-$c"; done); do
    gh repo view "$repo" >/dev/null 2>&1 || continue
    if gh repo delete "$repo" --yes >/dev/null 2>&1; then ok "deleted $repo"
    else SKIPPED+=("delete https://github.com/$repo/settings"); warn "couldn't delete $repo"; fi
  done
  if confirm "Delete the saved tokens and work files in $STATE_DIR (the write-up is kept)?"; then
    rm -rf "$WORK" "$LOGS" "$ENV_FILE"
    ok "removed; $RESULT_FILE is all that is left"
  else
    SKIPPED+=("delete $ENV_FILE (it holds the throwaway tokens)")
  fi
}
cleanup
pause

finish
